# ════════════════════════════════════════════
# BASE DE DONNÉES — PostgreSQL en prod, SQLite en local
# ════════════════════════════════════════════
DATABASE_URL = os.environ.get("DATABASE_URL", "")
if DATABASE_URL.startswith("postgres://"):
    DATABASE_URL = DATABASE_URL.replace("postgres://", "postgresql://", 1)

PG = bool(DATABASE_URL)

if PG:
    import psycopg2
    import psycopg2.extras

    def get_db():
        conn = psycopg2.connect(DATABASE_URL)
        conn.autocommit = False
        return conn

    def db_cursor(conn):
        return conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
else:
    import sqlite3
    SQLITE_PATH = os.environ.get("DATABASE_PATH", "neobank.db")

    def get_db():
        os.makedirs(os.path.dirname(SQLITE_PATH) if os.path.dirname(SQLITE_PATH) else ".", exist_ok=True)
        conn = sqlite3.connect(SQLITE_PATH)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        conn.execute("PRAGMA journal_mode = WAL")
        return conn

    def db_cursor(conn):
        return conn.cursor()


def fetchone(cur):
    row = cur.fetchone()
    return dict(row) if row else None


def fetchall(cur):
    return [dict(r) for r in cur.fetchall()]


def Q(sql):
    """Convertit les ? en %s pour PostgreSQL."""
    return sql.replace("?", "%s") if PG else sql


def demo_image_mime(image_data):
    if image_data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    if image_data.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if image_data[:4] == b"RIFF" and image_data[8:12] == b"WEBP":
        return "image/webp"
    return None


