# ════════════════════════════════════════════
def generate_card_number() -> str:
    """Génère un numéro Visa valide (algorithme de Luhn)."""
    while True:
        base = "4" + "".join(str(secrets.randbelow(10)) for _ in range(14))
        digits = [int(x) for x in base]
        total = sum(digits[-1::-2])
        for x in digits[-2::-2]:
            total += sum(divmod(x * 2, 10))
        check = (10 - total % 10) % 10
        number = base + str(check)
        # Vérification Luhn
        d2 = [int(x) for x in number]
        t2 = sum(d2[-1::-2])
        for x in d2[-2::-2]:
            t2 += sum(divmod(x * 2, 10))
        if t2 % 10 == 0:
            return number

