def get_iban_prefix(country: str) -> str:
    import unicodedata
    def normalize(s):
        return unicodedata.normalize("NFD", s).encode("ascii", "ignore").decode("ascii")
    norm = normalize(country)
    for k, v in COUNTRY_IBAN_PREFIX.items():
        if normalize(k) == norm:
            return v
    return "FR"

def generate_iban(country: str = "France") -> str:
    prefix = get_iban_prefix(country)
    check = secrets.randbelow(90) + 10
    bank  = secrets.randbelow(90000) + 10000
    acct  = secrets.randbelow(90_000_000_000) + 10_000_000_000
    return f"{prefix}{check}{bank:05d}{acct:011d}"

def validate_amount(value) -> float | None:
    try:
        amount = float(value)
        if not math.isfinite(amount):
            return None
        amount = round(amount, 2)
        return amount if 0 < amount <= 1_000_000 else None
    except (TypeError, ValueError, OverflowError):
        return None


