def demo_asset_price_history(symbol: str, minute: int | None = None) -> list[float]:
    asset = next(item for item in DEMO_ASSETS if item["symbol"] == symbol)
    minute = int(time.time() // 60) if minute is None else minute
    day_start = minute - minute % 1440
    seed = int.from_bytes(
        hashlib.sha256(f"{symbol}:{day_start}".encode("ascii")).digest()[:8],
        "big",
    )
    generator = random.Random(seed)
    price = asset["base_price"]
    history = []
    for _ in range(minute - day_start + 1):
        price *= 1 + generator.uniform(-0.0035, 0.0035)
        price = min(asset["base_price"] * 1.12, max(asset["base_price"] * 0.88, price))
        history.append(round(price, 8))
    visible_history = history[-60:]
    if len(visible_history) < 60:
        visible_history = [asset["base_price"]] * (60 - len(visible_history)) + visible_history
    return visible_history


def demo_asset_prices() -> dict[str, float]:
    minute = int(time.time() // 60)
    return {
        asset["symbol"]: demo_asset_price_history(asset["symbol"], minute)[-1]
        for asset in DEMO_ASSETS
    }


