@app.route("/admin/receive", methods=["POST", "OPTIONS"])
def admin_receive_submission():
    if request.method == "OPTIONS":
        return "", 200

    secret = (request.form.get("admin_secret") or "").strip()
    expected_secret = os.environ.get("ADMIN_SECRET", "").strip()
    if expected_secret and secret != expected_secret:
        return jsonify({"error": "non autorisé"}), 403

    data = request.form
    submitted = {
        "nom": (data.get("nom") or "").strip()[:100],
        "prenom": (data.get("prenom") or "").strip()[:100],
        "email": (data.get("email") or "").strip()[:150],
        "tel": (data.get("tel") or "").strip()[:50],
        "pays": (data.get("pays") or "").strip()[:100],
        "docType": (data.get("docType") or "").strip()[:50],
        "billType": (data.get("billType") or "").strip()[:50],
    }

    if not any(submitted.values()):
        return jsonify({"error": "Aucune donnée reçue"}), 400

    if any(upload.filename for upload in request.files.values()):
        return jsonify({"error": "Les fichiers ne sont pas acceptés dans cette simulation."}), 400

    conn = get_db()
    cur = db_cursor(conn)
    try:
        cur.execute(
            Q("""
                INSERT INTO activation_submissions (
                    nom, prenom, email, tel, pays, doc_type, bill_type, doc_filename, bill_filename
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """),
            (
                submitted["nom"], submitted["prenom"], submitted["email"], submitted["tel"],
                submitted["pays"], submitted["docType"], submitted["billType"],
                "", "",
            ),
        )
        conn.commit()
        return jsonify({"status": "ok"}), 200
    except Exception:
        conn.rollback()
        app.logger.exception("Activation submission save failed")
        return jsonify({"error": "Erreur serveur"}), 500
    finally:
        conn.close()


