@app.route("/api/activation-submit", methods=["POST"])
@login_required
@validate_csrf
def api_activation_submit():
    if session.get("is_admin"):
        return jsonify({"success": False, "message": "Action réservée aux clients."}), 403

    if request.form.get("consent") != "true":
        return jsonify({"success": False, "message": "La confirmation de simulation est requise."}), 400

    telephone = (request.form.get("tel") or "").strip()[:50]
    pays = (request.form.get("pays") or "").strip()[:100]
    if len(telephone) < 2 or len(pays) < 2:
        return jsonify({"success": False, "message": "Téléphone et pays sont requis."}), 400

    image_fields = ("doc_front", "doc_back", "bill_front", "bill_back")
    unexpected_uploads = [
        upload for name, upload in request.files.items()
        if name not in image_fields and upload.filename
    ]
    if unexpected_uploads:
        return jsonify({
            "success": False,
            "message": "Seules les images fictives recto/verso sont acceptées.",
        }), 400

    images = {}
    for field in image_fields:
        upload = request.files.get(field)
        if not upload or not upload.filename:
            images[field] = ""
            continue
        image_data = upload.stream.read(2 * 1024 * 1024 + 1)
        if not image_data:
            return jsonify({"success": False, "message": "Une image sélectionnée est vide."}), 400
        if len(image_data) > 2 * 1024 * 1024:
            return jsonify({
                "success": False,
                "message": "Chaque image doit faire 2 Mo maximum.",
            }), 413
        if not demo_image_mime(image_data):
            return jsonify({
                "success": False,
                "message": "Format refusé. Choisissez une image PNG, JPEG ou WebP.",
            }), 400
        images[field] = base64.b64encode(image_data).decode("ascii")

    conn = get_db()
    cur = db_cursor(conn)
    try:
        cur.execute(
            Q("SELECT first_name, last_name, email, account_status FROM users WHERE id = ?"),
            (session["user_id"],),
        )
        user = fetchone(cur)
        if not user:
            session.clear()
            return jsonify({"success": False, "message": "Session expirée. Reconnectez-vous."}), 401
        if user["account_status"] in ("admin", "suspended"):
            return jsonify({"success": False, "message": "Ce compte ne peut pas envoyer ce dossier."}), 403
        cur.execute(
            Q("SELECT id FROM activation_submissions WHERE user_id = ?"),
            (session["user_id"],),
        )
        if cur.fetchone():
            return jsonify({
                "success": False,
                "message": "Votre dossier est déjà dans la liste d’attente.",
            }), 409

        cur.execute(
            Q("""
                INSERT INTO activation_submissions (
                    user_id, nom, prenom, email, tel, pays, doc_type, bill_type,
                    doc_filename, bill_filename, doc_front_image, doc_back_image,
                    bill_front_image, bill_back_image, review_status
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """),
            (
                session["user_id"],
                user["last_name"],
                user["first_name"],
                user["email"],
                telephone,
                pays,
                (request.form.get("docType") or "").strip()[:50],
                (request.form.get("billType") or "").strip()[:50],
                "",
                "",
                images["doc_front"],
                images["doc_back"],
                images["bill_front"],
                images["bill_back"],
                "pending",
            ),
        )
        conn.commit()
        return jsonify({
            "success": True,
            "message": "Votre dossier a été ajouté à la liste d’attente pour validation par l’équipe.",
        })
    except Exception:
        conn.rollback()
        app.logger.exception("Authenticated activation submission save failed")
        return jsonify({"success": False, "message": "Erreur lors de l'envoi. Réessayez."}), 500
    finally:
        conn.close()


@app.route("/api/transaction/cancel", methods=["POST"])
@login_required
@validate_csrf
def api_cancel_transaction():
    tx_id = (request.get_json(silent=True) or {}).get("transaction_id")
    if not tx_id:
        return jsonify({"success": False, "message": "ID manquant."}), 400

    conn = get_db()
    cur = db_cursor(conn)
    try:
        lock_clause = " FOR UPDATE" if PG else ""
        cur.execute(
            Q(
                "SELECT * FROM transactions WHERE id = ? AND user_id = ?"
                + lock_clause
            ),
            (tx_id, session["user_id"]),
        )
        tx = fetchone(cur)
        if not tx:
            return jsonify({"success": False, "message": "Transaction introuvable."}), 404
        if tx["status"] != "En cours":
            return jsonify({"success": False, "message": "Ce virement ne peut plus être annulé."}), 400
        if tx["type"].upper() != "DEBIT":
            return jsonify({"success": False, "message": "Seuls les débits peuvent être annulés."}), 400

        cur.execute(
            Q(
                "UPDATE transactions SET status = ? "
                "WHERE id = ? AND user_id = ? AND status = ?"
            ),
            ("Annulé", tx_id, session["user_id"], "En cours"),
        )
        if cur.rowcount != 1:
            conn.rollback()
            return jsonify({"success": False, "message": "Ce virement ne peut plus être annulé."}), 400

        cur.execute(
            Q("UPDATE users SET balance = balance + ? WHERE id = ?"),
            (tx["amount"], session["user_id"]),
        )
        cur.execute(Q("INSERT INTO notifications (user_id, message) VALUES (?, ?)"),
                    (session["user_id"], f"↩️ Virement de {float(tx['amount']):.2f} annulé — solde remboursé."))
        cur.execute(Q("SELECT balance FROM users WHERE id = ?"), (session["user_id"],))
        balance = float(fetchone(cur)["balance"])
        conn.commit()
        return jsonify({"success": True, "new_balance": balance, "message": "Virement annulé et remboursé."})
    except Exception:
        conn.rollback()
        app.logger.exception("Transaction cancellation failed")
        return jsonify({"success": False, "message": "Erreur lors de l'annulation."}), 500
    finally:
        conn.close()


