@app.route("/api/registration/start", methods=["POST"])
@validate_csrf
def api_registration_start():
    data = request.get_json(silent=True) or {}
    fn = str(data.get("first_name", "")).strip()[:50]
    ln = str(data.get("last_name",  "")).strip()[:50]
    em = str(data.get("email",      "")).strip().lower()[:100]
    pw = str(data.get("password",   ""))
    phone = str(data.get("phone", "")).strip()[:50]
    birthdate = str(data.get("birthdate", "")).strip()[:20]
    city      = str(data.get("city",      "")).strip()[:100]
    country   = str(data.get("country",   "")).strip()[:100]
    currency  = str(data.get("currency",  "EUR")).strip()[:10]

    if not all([fn, ln, em, phone, pw, birthdate, city, country]):
        return jsonify({"success": False, "message": "Tous les champs sont requis."}), 400
    if len(pw) < 8:
        return jsonify({"success": False, "message": "Mot de passe trop court (8 caractères minimum)."}), 400
    if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", em):
        return jsonify({"success": False, "message": "Adresse email invalide."}), 400
    if len(phone) < 6:
        return jsonify({"success": False, "message": "Numéro de téléphone invalide."}), 400
    if currency not in {"EUR", "USD", "GBP", "CHF", "XOF", "XAF"}:
        return jsonify({"success": False, "message": "Devise invalide."}), 400

    ip = request.remote_addr or "unknown"
    if not check_rate_limit(ip):
        return jsonify({"success": False, "message": "Trop de tentatives. Réessayez dans 5 minutes."}), 429
    record_attempt(ip)

    conn = get_db(); cur = db_cursor(conn)
    try:
        cur.execute(Q("SELECT id FROM users WHERE email = ?"), (em,))
        if cur.fetchone():
            return jsonify({"success": False, "message": "Un compte existe déjà avec cet e-mail."}), 409

        now_timestamp = int(time.time())
        cur.execute(Q("SELECT * FROM registration_requests WHERE email = ?"), (em,))
        existing_request = fetchone(cur)
        if existing_request and existing_request["expires_at"] > now_timestamp:
            matches_existing = (
                existing_request["first_name"] == fn
                and existing_request["last_name"] == ln
                and existing_request["phone"] == phone
                and existing_request["birthdate"] == birthdate
                and existing_request["city"] == city
                and existing_request["country"] == country
                and existing_request["currency"] == currency
                and check_password_hash(existing_request["password_hash"], pw)
            )
            if not matches_existing:
                return jsonify({
                    "success": False,
                    "message": "Une demande est déjà en cours pour cette adresse. Revenez avec les mêmes informations.",
                }), 409
            if existing_request["failed_attempts"] >= 5:
                return jsonify({
                    "success": False,
                    "message": "Cette demande est verrouillée. Vous pourrez en créer une nouvelle après l’expiration du code.",
                }), 429
            session["registration_request_id"] = existing_request["id"]
            return jsonify({
                "success": True,
                "message": "Votre demande précédente est toujours active. Utilisez le même code communiqué par le service.",
                "resumed": True,
            })

        if existing_request:
            cur.execute(
                Q("DELETE FROM registration_requests WHERE id = ?"),
                (existing_request["id"],),
            )

        verification_code = f"{secrets.randbelow(10_000):04d}"
        expires_at = now_timestamp + 24 * 60 * 60
        cur.execute(Q("""
            INSERT INTO registration_requests (
                first_name, last_name, email, phone, password_hash,
                birthdate, city, country, currency, verification_code, expires_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """), (
            fn, ln, em, phone, generate_password_hash(pw),
            birthdate, city, country, currency, verification_code, expires_at,
        ))

        if PG:
            cur.execute("SELECT lastval() AS id")
            request_id = fetchone(cur)["id"]
        else:
            request_id = cur.lastrowid
        conn.commit()
        session["registration_request_id"] = request_id
        return jsonify({
            "success": True,
            "message": "Demande transmise au service. Saisissez le code à 4 chiffres que l’administrateur vous communiquera.",
        })
    except Exception:
        conn.rollback()
        app.logger.exception("Registration request creation failed")
        return jsonify({"success": False, "message": "Erreur serveur. Réessayez."}), 500
    finally:
        conn.close()


@app.route("/api/registration/verify", methods=["POST"])
@validate_csrf
def api_registration_verify():
    request_id = session.get("registration_request_id")
    data = request.get_json(silent=True) or {}
    code = str(data.get("verification_code", "")).strip()
    if not request_id or not re.fullmatch(r"\d{4}", code):
        return jsonify({"success": False, "message": "Saisissez le code à 4 chiffres envoyé par le service."}), 400

    ip = request.remote_addr or "unknown"
    if not check_rate_limit(ip):
        return jsonify({"success": False, "message": "Trop de tentatives. Réessayez dans 5 minutes."}), 429
    record_attempt(ip)

    conn = get_db()
    cur = db_cursor(conn)
    try:
        cur.execute(
            Q("SELECT * FROM registration_requests WHERE id = ?" + (" FOR UPDATE" if PG else "")),
            (request_id,),
        )
        registration = fetchone(cur)
        if not registration:
            session.pop("registration_request_id", None)
            return jsonify({"success": False, "message": "Demande introuvable. Recommencez l’inscription."}), 404
        if registration["expires_at"] <= int(time.time()):
            session.pop("registration_request_id", None)
            return jsonify({"success": False, "message": "Ce code a expiré. Recommencez l’inscription."}), 410
        if registration["failed_attempts"] >= 5:
            session.pop("registration_request_id", None)
            return jsonify({"success": False, "message": "Cette demande est verrouillée. Recommencez l’inscription."}), 429
        if not hmac.compare_digest(code, registration["verification_code"]):
            cur.execute(
                Q("UPDATE registration_requests SET failed_attempts = failed_attempts + 1 WHERE id = ?"),
                (request_id,),
            )
            conn.commit()
            remaining = max(0, 4 - registration["failed_attempts"])
            return jsonify({
                "success": False,
                "message": f"Code incorrect. Il vous reste {remaining} essai(s).",
            }), 400

        cur.execute(Q("SELECT id FROM users WHERE email = ?"), (registration["email"],))
        if cur.fetchone():
            conn.rollback()
            session.pop("registration_request_id", None)
            return jsonify({"success": False, "message": "Un compte existe déjà avec cet e-mail."}), 409

        card = generate_card_number()
        iban = generate_iban(registration["country"])
        now = datetime.now()
        cvv = f"{secrets.randbelow(900) + 100}"
        expiry = f"{now.month:02d}/{(now.year + 5) % 100:02d}"
        cur.execute(Q("""
            INSERT INTO users (
                first_name, last_name, email, phone, password_hash, balance,
                card_number, iban, birthdate, city, country, currency, card_cvv, card_expiry
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """), (
            registration["first_name"], registration["last_name"], registration["email"],
            registration["phone"], registration["password_hash"], 0.00,
            card, iban, registration["birthdate"], registration["city"],
            registration["country"], registration["currency"], cvv, expiry,
        ))
        if PG:
            cur.execute("SELECT lastval() AS id")
            user_id = fetchone(cur)["id"]
        else:
            user_id = cur.lastrowid
        cur.execute(
            Q("INSERT INTO notifications (user_id, message) VALUES (?, ?)"),
            (user_id, f"🎉 Bienvenue chez NeaBank, {registration['first_name']} ! Votre compte de simulation est prêt."),
        )
        cur.execute(Q("DELETE FROM registration_requests WHERE id = ?"), (request_id,))
        conn.commit()

        session.clear()
        session["user_id"] = user_id
        session["user_name"] = f"{registration['first_name']} {registration['last_name']}"
        session["is_admin"] = False
        session.permanent = True
        generate_csrf_token()
        email_bienvenue(
            registration["email"],
            registration["first_name"],
            registration["last_name"],
            iban,
        )
        return jsonify({"success": True, "redirect": "/activation"})
    except Exception:
        conn.rollback()
        app.logger.exception("Registration verification failed")
        return jsonify({"success": False, "message": "Erreur serveur. Réessayez."}), 500
    finally:
        conn.close()


