@app.route("/api/login", methods=["POST"])
@validate_csrf
def api_login():
    ip = request.remote_addr
    if not check_rate_limit(ip):
        return jsonify({"success": False, "message": "Trop de tentatives. Attendez 5 minutes."}), 429

    data = request.get_json(silent=True) or {}
    em   = str(data.get("email",    "")).strip().lower()
    pw   = str(data.get("password", ""))

    conn = get_db(); cur = db_cursor(conn)
    cur.execute(Q("SELECT * FROM users WHERE email = ?"), (em,))
    user = fetchone(cur); conn.close()

    if not user or not check_password_hash(user["password_hash"], pw):
        record_attempt(ip)
        return jsonify({"success": False, "message": "Email ou mot de passe incorrect."}), 401

    clear_attempts(ip)

    if user["account_status"] == "suspended":
        session.clear()
        session["user_id"]  = user["id"]
        session["is_admin"] = False
        generate_csrf_token()
        return jsonify({"success": True, "redirect": "/suspended"})

    session.clear()
    session["user_id"]   = user["id"]
    session["user_name"] = f"{user['first_name']} {user['last_name']}"
    session["is_admin"]  = (user["account_status"] == "admin")
    session.permanent    = True
    generate_csrf_token()
    return jsonify({
        "success": True,
        "redirect": "/admin" if session["is_admin"] else "/dashboard"
    })


